class initialize {
public:
  initialize(int &argc, char **&argv);
  ~initialize();
  double elapsed_time() { return wall_time() - t_start; }

private:
  double t_start;
};

enum derived_component {
  Sx = 100,
  Sy,
  Sr,
  Sp,
  Sz,
  EnergyDensity,
  D_EnergyDensity,
  H_EnergyDensity
};

enum field_type {
  E_stuff = 0,
  H_stuff = 1,
  D_stuff = 2,
  B_stuff = 3,
