// Construct a well-conditioned 3x3 complex matrix V and invert it into Vinv.
// Ensure V is invertible by building it as a diagonally dominant matrix.
{
    std::complex<double> V[9];
    std::complex<double> Vinv[9];

    // Random small off-diagonals
    auto small = [&](){ return std::complex<double>(*FUZZ_PARAM(double) * 1e-3, *FUZZ_PARAM(double) * 1e-3); };
    // Positive diagonal entries in [0.1, 10.1)
    auto diagv = [&](int i){
        double base = static_cast<double>(*FUZZ_PARAM(unsigned int) % 1000) / 100.0 + 0.1; // 0.1 .. 10.09
        (void)i; return std::complex<double>(base, 0.0);
    };

    // Fill V as diagonally dominant: V = D + E, with ||E|| small
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            int idx = r * 3 + c;
            if (r == c) V[idx] = diagv(r);
            else V[idx] = small();
        }
    }

    // Invert
    meep::matrix_invert(Vinv, V);

    // Validate Vinv is an inverse of V within numerical tolerance: ||V*Vinv - I||_max < 1e-6
    double max_err = 0.0;
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            std::complex<double> acc(0.0, 0.0);
            for (int k = 0; k < 3; ++k) acc += V[r*3 + k] * Vinv[k*3 + c];
            std::complex<double> target = (r == c) ? std::complex<double>(1.0, 0.0) : std::complex<double>(0.0, 0.0);
            std::complex<double> diff = acc - target;
            double err = std::abs(diff);
            if (err > max_err) max_err = err;
        }
    }
    if (max_err > 1e-6) { FUZZ_BAIL(); }

    // Validation: Builds a guaranteed-invertible matrix, calls matrix_invert, and checks the product against identity with a strict tolerance.
}

// Generate a valid set of inputs and validate basic properties of the output grid.
{
    // Nfreq in [1, 1024]
    size_t Nfreq = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
    double fmin = *FUZZ_PARAM(double);
    double fmax = *FUZZ_PARAM(double);

    std::vector<double> v = meep::linspace(fmin, fmax, Nfreq);

    // Must contain exactly Nfreq points
    FUZZ_ASSERT(v.size() == Nfreq, "linspace size mismatch");

    // Endpoints must be inclusive when Nfreq>=2
    if (Nfreq >= 2) {
        FUZZ_ASSERT(v.front() == fmin, "linspace first element must equal fmin");
        FUZZ_ASSERT(v.back()  == fmax, "linspace last element must equal fmax");
        // Check linear spacing: successive differences are equal within tolerance
        double step = (fmax - fmin) / static_cast<double>(Nfreq - 1);
        double tol = 1e-12 * (1.0 + std::fabs(step));
        for (size_t i = 1; i < v.size(); ++i) {
            double di = v[i] - v[i-1];
            if (std::fabs(di - step) > tol) { FUZZ_BAIL(); }
        }
    } else {
        // For Nfreq==1, common convention is [fmin]
        FUZZ_ASSERT(v.front() == fmin, "linspace(N=1) should return [fmin]");
    }

    // Validation: Inputs satisfy Nfreq>=1; the result is verified for size, endpoints, and constant spacing (when applicable).
}

